import{_ as t,o,c as d,a2 as n}from"./chunks/framework.Boholvbs.js";const p=JSON.parse('{"title":"Feature parity across the clients","description":"","frontmatter":{},"headers":[],"relativePath":"parity.md","filePath":"parity.md"}'),s={name:"parity.md"};function a(r,e,i,h,c,l){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="feature-parity-across-the-clients" tabindex="-1">Feature parity across the clients <a class="header-anchor" href="#feature-parity-across-the-clients" aria-label="Permalink to &quot;Feature parity across the clients&quot;">​</a></h1><p>nanoMuse is one agent on every device: the phone (Android, iOS), the computer (nanoMuse Desktop — the <code>dsh-nanomuse</code> harness bundle in the Electron shell) and the browser (nanoMuse Web, served by the runtime). The rule since 0.1.32 is the <strong>union</strong>: whatever one client can do, every client does, unless the platform itself forbids it (the computer does not build a mini-Linux the way the phone does; iOS does not let an app drive another). This page is the ledger — what each client has, what is platform-specific by design, and what is still open for a decision.</p><p>Legend: <strong>✓</strong> done · <strong>◐</strong> partial (what is missing is in the note) · <strong>—</strong> not on this client · <strong>n/a</strong> platform-specific, not meant to be.</p><h2 id="account-nanomuse-cloud" tabindex="-1">Account (nanoMuse Cloud) <a class="header-anchor" href="#account-nanomuse-cloud" aria-label="Permalink to &quot;Account (nanoMuse Cloud)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Android</th><th>iOS</th><th>Desktop</th><th>Web</th></tr></thead><tbody><tr><td>Sign in with a code (phone / e-mail)</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>Sign in with a password</td><td>✓</td><td>✓ 0.1.32</td><td>✓</td><td>✓</td></tr><tr><td>Invite code at sign-in</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Amounts from the relay (<code>/v1/config</code>) before sign-in</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Allowance in yuan, 80 % heads-up</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>&quot;Ways on&quot; when the pool is spent (own key · invite · star)</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Invite code and link, earnings</td><td>✓</td><td>✓ 0.1.32</td><td>✓</td><td>✓</td></tr><tr><td>Usage by kind and by model, today / all time</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Set / change / remove the password</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Signed-in devices, revoke one, sign out everywhere</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Account timeline (sign-ins, settings, refusals)</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Delete account</td><td>✓</td><td>✓ 0.1.32</td><td>✓ 0.1.32</td><td>✓</td></tr><tr><td>Data controls (what the relay keeps of the chats)</td><td>✓</td><td>✓ 0.1.33</td><td>✓</td><td>✓</td></tr><tr><td>Own-key presets (Bailian · OpenRouter, by region)</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td></tr><tr><td>Chat model and Hands model as two settings (<code>deepseek-v4.1-flash</code> / <code>qwen3.8-27b</code>, the relay&#39;s <code>for</code>)</td><td>✓ 0.1.34</td><td>✓ 0.1.34 <em>(chat; no hands)</em></td><td>✓ 0.1.34</td><td>✓ 0.1.34</td></tr><tr><td>&quot;Ways on&quot; ordered by region (Bailian first on the mainland, OpenRouter first elsewhere)</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td></tr></tbody></table><h2 id="the-agent-in-the-chat" tabindex="-1">The agent in the chat <a class="header-anchor" href="#the-agent-in-the-chat" aria-label="Permalink to &quot;The agent in the chat&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Android</th><th>iOS</th><th>Desktop</th><th>Web</th></tr></thead><tbody><tr><td>Status line says what it is on, never &quot;Thinking&quot;</td><td>✓</td><td>✓ 0.1.32 <em>&quot;is on it&quot;</em></td><td>✓</td><td>✓</td></tr><tr><td>Status line = the step&#39;s own words (<code>step</code>: <em>打开携程网站</em>), never the raw command</td><td>✓ 0.1.33</td><td>✓ 0.1.33</td><td>✓ 0.1.33</td><td>✓ 0.1.33</td></tr><tr><td>&quot;Show the agent&#39;s steps&quot;, on by default since 0.1.37 (a stored off stays off)</td><td>✓ 0.1.37 (<code>nm.show_steps</code>)</td><td>✓ 0.1.37 (<code>nanomuse.show_steps</code>) <em>(2)</em></td><td>✓ 0.1.37</td><td>✓ 0.1.37</td></tr><tr><td>Star asks at the relay&#39;s moments (<code>/v1/nudges</code>: sign-in · 3rd / 10th / 30th task · 7th / 30th day · a goal reached · a new look · allowance spent; 7 days apart, 4 per device; never in the first conversation)</td><td>✓ 0.1.35</td><td>✓ 0.1.35 <em>(3)</em></td><td>✓ 0.1.35</td><td>✓ 0.1.35</td></tr><tr><td>First conversation: the app speaks first, asks what to call you, the model&#39;s <code>nanomuse-naming</code> fence becomes the naming card</td><td>✓</td><td>✓ 0.1.34</td><td>✓ 0.1.35 <em>(25)</em></td><td>✓</td></tr><tr><td>First run: &quot;Sign in — free&quot; before anything else</td><td>✓</td><td>✓ 0.1.32 <em>(4)</em></td><td>✓</td><td>✓</td></tr><tr><td>Approval cards, three tiers, remembered grants</td><td>✓</td><td>upstream&#39;s</td><td>✓</td><td>✓</td></tr><tr><td>Approvals answered outside the app while the hands work</td><td>✓ 0.1.33 capsule <em>Allow / Deny</em></td><td>n/a <em>(10)</em></td><td>✓ 0.1.34 stage <em>Allow once / Always in app / Deny</em>, capsule when the window is behind <em>(17)</em></td><td>n/a</td></tr><tr><td>Hand-over: a login / code / payment / CAPTCHA goes back to the person, the agent waits and resumes (holds)</td><td>✓ 0.1.33 <code>hand_over</code></td><td>— <em>(16)</em></td><td>✓ 0.1.34 <em>Your turn — Done</em>, <em>I&#39;ll take it</em> <em>(16)</em></td><td>✓ 0.1.34 drivable browser viewer, hold cards <em>(16)</em></td></tr><tr><td>Face tap opens the agent page (Change avatar · Edit name · studio; Activity · Approvals · Daily · Soul &amp; memory; share card)</td><td>✓</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ Muse page</td></tr><tr><td>Change the look from the chat (the same words, four candidates, pick by words, regenerate)</td><td>✓</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ studio intercept, reference picture 0.1.34</td></tr></tbody></table><h2 id="connectors-agents-devices" tabindex="-1">Connectors, agents, devices <a class="header-anchor" href="#connectors-agents-devices" aria-label="Permalink to &quot;Connectors, agents, devices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Android</th><th>iOS</th><th>Desktop</th><th>Web</th></tr></thead><tbody><tr><td>Connectors catalogue (75 remote MCP servers, sign in)</td><td>✓ 0.1.32 <em>(5)</em></td><td>✓ 0.1.33 <em>(6)</em></td><td>✓</td><td>— <em>(7)</em></td></tr><tr><td>Services without dynamic registration (GitHub, Slack, Discord, …) ask for an OAuth client id</td><td>✓ 0.1.33</td><td>✓ 0.1.33</td><td>✓ 0.1.33</td><td>— <em>(7)</em></td></tr><tr><td>MCP servers by hand (URL / command)</td><td>✓ <em>Your own servers</em> under Connectors 0.1.33</td><td>✓ <em>Your own servers</em> under Connectors 0.1.33</td><td>✓ (harness)</td><td>✓</td></tr><tr><td>Connections shared across the account&#39;s devices (the profile&#39;s <code>connectors</code>; never a credential)</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ 0.1.34</td><td>✓ 0.1.34 <em>(18)</em></td></tr><tr><td>Chat apps: Feishu · DingTalk · WeCom · Telegram answer as the agent (pairing codes, allowlists, deliver here)</td><td>— <em>(22)</em></td><td>— <em>(22)</em></td><td>✓ 0.1.34 the web screen</td><td>✓ 0.1.34 <em>Settings → Chat apps</em></td></tr><tr><td>Skills</td><td>✓ upstream</td><td>✓ upstream</td><td>— <em>(8)</em></td><td>✓</td></tr><tr><td>Coding agents (Cursor, Codex, Claude Code on the computers)</td><td>✓</td><td>✓ 0.1.34 over the hub <em>(9)</em></td><td>— <em>(8)</em></td><td>✓</td></tr><tr><td>Devices of the account, remote control, rename, forget</td><td>✓</td><td>◐ list, Reach sheet 0.1.33</td><td>✓</td><td>✓</td></tr><tr><td>Hands — the device&#39;s own screen as a hand</td><td>✓</td><td>n/a <em>(10)</em></td><td>✓ the screen; on macOS one window while the person keeps the mouse, per-app grants, glow and capsule out of the shots <em>(19)</em></td><td>n/a</td></tr><tr><td>Installed and latest version, side by side (<code>nanomuse.cn/dl/index.json</code> first, GitHub second, a day&#39;s cache)</td><td>✓ 0.1.35 Settings → Version</td><td>✓ 0.1.35 Settings → Version</td><td>✓ 0.1.35 About, Settings row</td><td>✓ 0.1.35 Settings</td></tr><tr><td>A black capture is an error with the fix (Screen Recording, Wayland), never a picture</td><td>n/a</td><td>n/a</td><td>✓ 0.1.33</td><td>n/a</td></tr><tr><td>macOS permissions read back live; <em>Open System Settings</em> after an ask; Screen Recording relaunch notice</td><td>n/a</td><td>n/a</td><td>✓ 0.1.33; 0.1.35: only <em>nanoMuse Desktop</em> has to be switched on, <em>Try it</em> rows, a restart dialog when Screen Recording flips on <em>(26)</em></td><td>n/a</td></tr><tr><td>Mini-Linux sandbox on the device</td><td>✓</td><td>✓ upstream (iSH)</td><td>n/a — the runtime&#39;s own sandbox</td><td>n/a</td></tr></tbody></table><h2 id="face-rooms-look" tabindex="-1">Face, rooms, look <a class="header-anchor" href="#face-rooms-look" aria-label="Permalink to &quot;Face, rooms, look&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Android</th><th>iOS</th><th>Desktop</th><th>Web</th></tr></thead><tbody><tr><td>Avatar studio: generate, pick, pose; the face shared across devices</td><td>✓</td><td>✓ 0.1.33 <em>(11)</em></td><td>✓</td><td>✓</td></tr><tr><td>Motion clips for a drawn face (idle · working · waiting · happy; <code>wan2.2-i2v-flash</code>; <em>Animate the avatar after a change</em>)</td><td>✓</td><td>✓ 0.1.35</td><td>✓ 0.1.35 header, sidebar, capsule</td><td>— <em>(27)</em></td></tr><tr><td>Emoji faces</td><td>◐ falls back to the dragon <em>(12)</em></td><td>◐ falls back to the dragon <em>(12)</em></td><td>✓</td><td>✓</td></tr><tr><td>Theme colour swatches</td><td>—</td><td>—</td><td>— removed 0.1.33 <em>(13)</em></td><td>—</td></tr><tr><td>Accent follows the avatar</td><td>✓</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td>Rooms: Feed · Ideas · Goals · Library</td><td>✓</td><td>✓ 0.1.34 with a scheduler <em>(11)</em></td><td>✓ 0.1.34 on the phone&#39;s fence protocol</td><td>✓</td></tr><tr><td>Ideas by kind: chat · routine (at a time) · goal (a category)</td><td>✓</td><td>✓ 0.1.34</td><td>✓ 0.1.34 the phone&#39;s list</td><td>✓ 0.1.34</td></tr><tr><td>First run: the phone&#39;s pages (sign in · password · which model answers · models · permissions · notifications · meet), then the shell; never skipped on a fresh install</td><td>✓</td><td>✓ 0.1.34, notifications page 0.1.35 <em>(4)</em></td><td>✓ 0.1.35 kept by the host in <code>firstrun.json</code> <em>(25)</em></td><td>✓ onboarding</td></tr><tr><td>Feed opens on the intro card (<em>Write it now</em>), the first day is written after the first conversation, a daily routine at 08:00</td><td>✓</td><td>✓ 0.1.35</td><td>✓ 0.1.35</td><td>✓ 0.1.35</td></tr><tr><td>Ideas prefilled with the curated list (<code>ideas.{en,zh}.json</code>, byte for byte, with a test)</td><td>✓</td><td>✓</td><td>✓ 0.1.34; empty-when-bundled bug fixed 0.1.35</td><td>✓ 0.1.35</td></tr><tr><td>Splash: wordmark and the person&#39;s own face, never the dragon</td><td>✓</td><td>✓ system launch screen</td><td>✓ 0.1.35</td><td>n/a</td></tr><tr><td>Settings as Muse cards in one order (Image &amp; video models · Avatar · Computers · Appearance · … · Version)</td><td>✓</td><td>✓ 0.1.35</td><td>✓ sections</td><td>✓ sections</td></tr><tr><td>Memory as a room</td><td>— settings page <em>(14)</em></td><td>—</td><td>✓</td><td>✓</td></tr><tr><td>Live stage / browser viewer while the hands work</td><td>✓ stage</td><td>n/a <em>(10)</em></td><td>✓ live stage — movable, resizable, remembered 0.1.33; Allow/Deny, holds, glow 0.1.34</td><td>✓ browser viewer you can drive 0.1.34</td></tr><tr><td>Quick chat (global shortcut)</td><td>n/a</td><td>n/a</td><td>✓</td><td>n/a</td></tr><tr><td>Widgets</td><td>✓ upstream</td><td>✓ upstream</td><td>n/a</td><td>n/a</td></tr></tbody></table><h2 id="open-for-a-decision-the-next-next-list" tabindex="-1">Open for a decision (the &quot;next-next&quot; list) <a class="header-anchor" href="#open-for-a-decision-the-next-next-list" aria-label="Permalink to &quot;Open for a decision (the &quot;next-next&quot; list)&quot;">​</a></h2><p>These are the gaps left open on purpose since 0.1.32 — either the platform makes them a different design, or they are large enough that the call is the maintainer&#39;s. Numbers match the notes above; a settled item keeps its number and says how it went.</p><ol><li><strong>iOS · Data controls</strong> — done in 0.1.33 (<code>NanoMuseDataControls.swift</code>).</li><li><strong>iOS · Steps.</strong> The header line (and the face) are there since 0.1.33; the steps of the message still running stay visible even with the setting off, finished messages hide them. <em>Hide them too, now that the status line says what is going on?</em></li><li><strong>iOS · Star after the first task</strong> — done in 0.1.33, as a card pinned under the header (the message list is a UICollectionView; nothing can be placed under the last message). A cancelled turn counts as finished, the stream has no cancel signal. In 0.1.35 the card follows the relay&#39;s policy like everyone else (28): no ask in the first conversation, the 3rd task is the first moment.</li><li><strong>iOS · First run</strong> — done in 0.1.34 (<code>NanoMuseFirstRun.swift</code>, the Android <code>needed / stage</code> logic). Shown to anyone without a Cloud account, so a person upgrading who only ever used their own key sees it once; <em>All settings</em> skips it.</li><li><strong>Android · OAuth connectors need a device test.</strong> Discovery, dynamic client registration, PKCE and the token written into the entry&#39;s <code>Authorization</code> header compile and follow the desktop&#39;s flow line by line, but no connector was signed into on a device before 0.1.32 (no emulator on the build machine); the same goes for 0.1.33&#39;s client-id path (GitHub, Slack, …) and the browser hand-over. Key and open connectors are plain MCP entries and need nothing new. The token ends up in <code>servers.json</code> next to API keys, as the in-guest client reads it; refresh runs at app start and when the page opens, not in the background.</li><li><strong>iOS · Connectors</strong> — done in 0.1.33 (<code>NanoMuseConnectors.swift</code>, the Android flow ported), with the same caveat as 5: compiled, not yet signed into on a device.</li><li><strong>Web · Connectors.</strong> The runtime would have to run the OAuth flow itself and hold the tokens (the desktop does it in the harness host). The web app has MCP servers by hand. <em>Decision: run the flow in the runtime (<code>nanomuse mcp</code> already bridges connectors), or point the web app at a desktop on the account?</em></li><li><strong>Desktop · Skills and coding agents pages.</strong> The harness has its own skills; the coding agents live on the computer the desktop runs on, so a page would show the local CLIs. <em>Recommendation: coding agents page yes (the web app has one), skills no (duplicate).</em></li><li><strong>iOS · Coding agents</strong> — done in 0.1.34 (<code>NanoMuseCoding.swift</code>, the hub&#39;s <code>coding.*</code>).</li><li><strong>iOS · Hands.</strong> iOS does not let an app drive another; App Intents / Shortcuts are the door. Not planned as &quot;hands&quot;. Settled in 0.1.36: the Settings row is there (<em>Hands — Not on iPhone</em>) and opens a page that says why, and what a computer of the account can do; the iPhone&#39;s own Muse takes <code>task</code> calls from the other devices while the app is open (<code>@iPhone …</code>).</li><li><strong>iOS · The Muse shell</strong> — done in 0.1.33 on the iPhone; in 0.1.34 Feed and Goals are real (<code>NanoMuseScheduler.swift</code>: foreground catch-up, <code>BGAppRefreshTask</code>, a local notification at the set time), the iPad runs the shell too, the shell and header switches are in the nanoMuse settings page, and the studio draws through the relay or your own Bailian key. Left: a routine runs in the background only when iOS gives the refresh task a slot — the copy says so (<em>at the set time the phone reminds you to open it</em>); the hub route (a computer of the account runs them) is still the sure one. The iPad&#39;s layout is the iPhone&#39;s, larger — settled in 0.1.35: no split layout of its own.</li><li><strong>Android and iOS · Emoji faces.</strong> A face set to an emoji on the web or the desktop shows the dragon on the phones. Small.</li><li><strong>Theme colour swatches</strong> — settled in 0.1.33: removed from the desktop; one rule everywhere, the accent follows the avatar.</li><li><strong>Android · Memory as a room.</strong> It is a settings page on the phone, a room elsewhere. Design call.</li><li><strong>Browser viewer on the desktop.</strong> The live stage shows the hands; a page viewer like the web app&#39;s is not there. Design call.</li><li><strong>Hand-over on the desktop and the web</strong> — settled in 0.1.34, both: <em>holds</em> in the runtime (<code>nanomuse/agent/holds.py</code>; <code>hand_over</code> on <code>browser</code>, <code>computer_act</code>, <code>phone_act</code>; <code>POST /api/holds</code>, <code>/done</code>; <code>hold</code> events; the agent waits up to ten minutes and looks again). The desktop&#39;s stage shows <em>Your turn — Done</em> and <em>I&#39;ll take it</em>; the web&#39;s browser viewer can be driven (<em>Take over</em>, click, type, scroll, URL, <em>Done</em>). Left: iOS has no hands, so nothing to hand over there (10).</li><li><strong>Desktop · approvals outside the window</strong> — settled in 0.1.34: the live stage carries <em>Allow once / Always in &lt;app&gt; / Deny</em>, and a small always-on-top capsule shows the same card when the main window is not in front. Left to check on a Mac: the capsule&#39;s <code>showInactive</code> must not steal focus from the app being driven — on the Mac task sheet (<code>docs/tasks/mac-check-0.1.36.md</code>, D).</li><li><strong>Connections shared across devices</strong> — settled in 0.1.34: the profile&#39;s <code>connectors</code> (relay 0.17; merged per device, 64 at most, a key-like field name is a 400), four clients read and write it, the other devices&#39; entries show as <em>Connected on &lt;device&gt; — sign in here</em>. The credential never leaves the device that minted it.</li><li><strong>Desktop · hands that do not fight the person</strong> — settled for macOS in 0.1.34 the way the Codex app does it: <em>window mode</em> (<code>nanomuse/computer/mac_window.py</code>; <code>[hands] mode = auto</code>) captures one application&#39;s window and posts the events to its process, so the person keeps the mouse; each application asks once (<em>Let &lt;Muse&gt; use &lt;App&gt;?</em>). Elsewhere the screen is shared, with the UI-TARS-style glow and the overlays kept out of the shots. Left: Linux and Windows have no window mode (a virtual display or a second session would be the port — Linux first, cheapest); the macOS path is written against the Quartz APIs and must be tried on a Mac (Screen Recording fallback, AX-less clicks, Retina mapping, scroll direction). Settled in 0.1.35: <code>auto</code> stays the default, with a fail-safe — when the Quartz layer itself fails (not &quot;the window went away&quot;, which is retried every look) the hands fall back to the whole screen for the rest of that target and say so once; an explicit <code>window</code> mode keeps trying. Settled in 0.1.36 for the pointer itself: the desktop&#39;s hands are UI-TARS-desktop&#39;s operator moved into the Electron main process (<code>harness/desktop/src/operator.ts</code>, <code>@computer-use/nut-js</code>, loopback HTTP to the runtime&#39;s <code>desktop</code> backend), and the model&#39;s coordinates are pixels of the picture it saw, mapped once to the operator&#39;s screen (<code>nanomuse/computer/coords.py</code>) — the clicks that landed beside their targets on scaled displays are gone (≤1 px on a 4K display at scale 2). Left to try on a Mac and on Windows: the native addon in the packaged app, the coordinate space (points on a Mac), scroll units, ⌘ for <code>ctrl</code>, content protection — the Mac task sheet, F.</li><li><strong>Services without a public remote MCP server</strong> — the chat apps are settled in 0.1.34 the way nanobot does it: 飞书, 钉钉, 企业微信 and Telegram are <em>channels</em> the agent answers in (<code>nanomuse/channels/</code>, the vendors&#39; long-connection SDKs, no public address, pairing codes), which is what most people wanted from them. Still open as <em>connectors</em> (the agent reading or acting in the service): Zoom, LinkedIn, Zoho Invoice, WHOOP, 腾讯文档, 滴答清单, 网易邮箱, QQ 邮箱, 微信读书 — each a bridge of its own over the vendor&#39;s REST API, one developer account per vendor. <em>Decision: which, if any, are worth a bridge?</em></li><li><strong>Hands on Linux under Wayland.</strong> The capture and the pointer need X11 or XWayland today; a Wayland session gives a black frame (now an error with the hint). Since 0.1.36 the operator says so itself (<code>/info</code> → <code>available: false</code>, <em>Wayland session … log in with Xorg</em>), and the Hands card shows the reason; UI-TARS-desktop has no Wayland path either. The portal route (<code>xdg-desktop-portal</code> ScreenCast + <code>libei</code>) would make it work natively, at the cost of a permission dialog per session. <em>Decision: worth it before the Linux desktop is promoted?</em></li><li><strong>Chat apps on the phones.</strong> The channels live in the runtime; the web app (and so the desktop) has the settings screen. Android and iOS would need an <code>/api/channels</code> client and the same card list (switch, fields, pairing codes, paired chats, Feishu QR) — the API and the strings are ready. <em>Decision: next version?</em> Also open: no vendor was connected end to end from the build machine (the SDK calls were checked offline against the real packages) — one test bot per vendor before announcing; Feishu sender names need <code>contact:user.base:readonly</code>; approvals from a chat are always <em>once</em>.</li><li><strong>Own-key presets and the chat default.</strong> After a Bailian or OpenRouter key is saved, the provider&#39;s <code>/models</code> list decides what is offered; <code>deepseek-v4.1-flash</code> is not moved to the front automatically (only the Cloud group has <code>followPick</code>). <em>Recommendation: promote it when the list has it.</em></li><li><strong>Relay billing of reasoning tokens.</strong> Counted as completion tokens; when a provider reports them separately and the count exceeds the completion count they are added, otherwise taken as included. A provider that reports them separately <em>and</em> smaller would be under-counted. <em>Decision: keep the heuristic, or switch per provider?</em></li><li><strong>Desktop · first run and first conversation</strong> — settled in 0.1.35 after the phone: the host keeps <code>firstrun.json</code> and never skips the pages on a fresh install; the app speaks first (three scripted lines, no tokens), asks what to call you, and the model&#39;s <code>nanomuse-naming</code> fence becomes the naming card (<code>take_name</code> / <code>ask_user_question</code> are gone). Left, by design: the scripted lines are a client overlay, not stored messages; the address is a memory line rather than a <code>GLOBAL.md</code> edit; the gear on the first-run pages dismisses them for the session only.</li><li><strong>Desktop · macOS permissions</strong> — re-audited in 0.1.35: TCC attributes the bundled runtime to the responsible process, so only <em>nanoMuse Desktop</em> has to be switched on (the words say so now; the runtime no longer appears as a second entry to hunt for). Left to try on a Mac: the <em>Try it</em> rows after a fresh grant, the restart dialog when Screen Recording flips on, the capsule&#39;s <code>showInactive</code> (17), window mode&#39;s AX-less clicks and Retina mapping (19), the face click after 0.1.36&#39;s change (no drag region under the face at all; the face below the title-bar band) — all on the Mac task sheet, <code>docs/tasks/mac-check-0.1.36.md</code>, written so that an agent on a Mac can run it end to end and send the fixes back.</li><li><strong>Web · motion clips.</strong> The clips are per device (drawn where the face lives: the phone, the iPhone, the desktop). The web app shows the still face. <em>Decision: draw them in the runtime too, or leave the web still?</em></li><li><strong>Star asks · what counts.</strong> The policy is the relay&#39;s (<code>/v1/admin/nudges</code>, console → Star asks) and reaches every client within a day without an update. Two small differences left: Android asks once per phone when the allowance is spent (the other clients the same); the first feed day is not written when the person changes the face during the naming conversation (the first run never reaches <em>done</em>). Small.</li><li><strong>One conversation on every device</strong> — settled in 0.1.36 (contract C7 in <code>docs/cloud.md</code>): the text of the chats lives on the relay (<code>/v1/sync/*</code>, relay 0.19), on by default when signed in, with the switch and the delete under Data controls on every client; one main conversation per account; what a device started on its own (routines, goals, the feed, work for another device) stays on it. One thread since 0.1.37 (contract C8): the main chat on every device is the union of what was said on all of them in time order, the other devices&#39; turns as read-only bubbles (<em>From Pixel 8</em>) the model reads too; a side chat from elsewhere is a chat on the device at once; the person&#39;s message goes up when sent, the reply at the turn&#39;s end; the whole history is backfilled on sign-in. The desktop appends the other devices&#39; turns to the dsh session log (<code>user/message</code>, source <code>nanomuse-sync</code>) and dresses them in the browser. Left: the dsh plugin has no delete, so an archived session is not a tombstone, a message deleted elsewhere is hidden rather than removed from the log; switching sync off on one device reaches the others at their next push or pull (a <code>409</code>), not at once; on iOS a pulled message that arrives late sits after the local ones (the OpenMinis store appends). <code>@&lt;device name&gt;</code> runs a turn on another device — computers whenever online, phones while the app is open; on iOS the mention goes to the hub directly (no <code>delegate</code> tool there) and the iPhone answers <code>task</code> calls itself.</li><li><strong>iOS · composer, bubbles, header</strong> — settled in 0.1.36 after the phone: the one-row pill, flat grey bubbles for the person, a floating translucent header. Left: on iOS 16–18 the transcript starts below the header&#39;s edge rather than scrolling under it (the UIKit list needs the inset passed down; to be tried on a device — the risk of covering the first message was not worth taking blind).</li><li><strong>Desktop · the operator on a Mac and on Windows.</strong> Ported from UI-TARS-desktop and proven on Linux X11; the native addon, the coordinate space (points on a Mac, physical pixels on Windows), scroll units, ⌘ for <code>ctrl</code>, content protection of the glow are on the Mac task sheet (<code>docs/tasks/mac-check-0.1.36.md</code>, F). Wayland stays item 21.</li></ol><h2 id="keeping-this-true" tabindex="-1">Keeping this true <a class="header-anchor" href="#keeping-this-true" aria-label="Permalink to &quot;Keeping this true&quot;">​</a></h2><ul><li>The desktop&#39;s connectors catalogue is the source (<code>harness/dsh-nanomuse/src/connectors-catalogue.ts</code>); <code>node scripts/connectors-json.mjs</code> writes the Android asset and the iPhone&#39;s bundled copy, <code>--check</code> (in the harness workflow) fails when either is stale.</li><li>Relay-facing code mirrors the same wire format on every client: <code>nanomuse/cloud.py</code> (runtime), <code>harness/dsh-nanomuse/src/relay.ts</code> (desktop), <code>io.github.nanomuse.cloud.NanoMuseCloud</code> (Android), <code>NanoMuse/NanoMuseCloud.swift</code> + <code>NanoMuseAccount.swift</code> (iOS). A new relay field lands in all four.</li><li>The star asks follow one policy everywhere — the relay&#39;s <code>/v1/nudges</code> (contract C1 in <code>docs/cloud.md</code>), with the same defaults built into every client: a <em>task</em> is a turn the person started that got a reply, never the first conversation, a routine, a feed post or a goal check-in; once per moment, <code>cooldown_days</code> apart, <code>max_asks</code> per device, never again after <em>Star on GitHub</em> (<code>nm.star.*</code> / <code>nanomuse.star.*</code>). Clients: <code>nanomuse/nudges.py</code>, <code>harness/dsh-nanomuse/src/nudges.ts</code>, <code>web/src/nudges.ts</code>, <code>io.github.nanomuse.community.Nudges</code>, <code>NanoMuse/NanoMuseNudges.swift</code>.</li><li>The release check reads the same two sources in the same order on every client: <code>https://nanomuse.cn/dl/index.json</code>, then GitHub&#39;s <code>releases/latest</code>; a day&#39;s cache; the row always shows the installed version too.</li><li>Conversation sync speaks one wire format (contract C7 in <code>docs/cloud.md</code>) from four clients and one relay: <code>cloud/nanomuse_cloud/sync.py</code>, <code>nanomuse/sync/</code> (runtime and web), <code>harness/dsh-nanomuse/src/sync.ts</code> (desktop), <code>io.github.nanomuse.sync</code> (Android), <code>NanoMuse/NanoMuseSync.swift</code> (iOS). Every client applies a page&#39;s conversations before its messages and moves its cursor only on a pull; every client pushes the person&#39;s lines and the final answer only — never tool steps, tool results or the system prompt — and leaves routines, goals, the feed and work for another device at home.</li><li><code>ideas.en.json</code> / <code>ideas.zh.json</code> are one file four times (Android assets, iOS Resources, <code>harness/dsh-nanomuse/assets</code>, <code>web/src/ideas</code>); the harness and web tests fail when a copy drifts.</li></ul>',16)])])}const u=t(s,[["render",a]]);export{p as __pageData,u as default};
